// Разбор вебхука «Откликнулся» от портала: проверяем поля контракта feed-item v1
// и готовим тела запросов для Espo и Todoist. Один вебхук — один элемент.
// Секретов здесь нет: адреса и ключи подставляют HTTP-ноды из $env.
const raw = $input.first().json.body || {};
// Адаптер портала шлёт {event, payload, emitted_at}; на всякий случай принимаем и плоское тело.
const b = raw.payload && typeof raw.payload === 'object' ? raw.payload : raw;
const required = ['external_id', 'title', 'url', 'text', 'source'];
const missing = required.filter((k) => b[k] === undefined || b[k] === null || b[k] === '');
if (missing.length) throw new Error('в теле вебхука нет полей: ' + missing.join(', '));

const ESPO_SOURCES = ['kc', 'kwork', 'fl', 'hh', 'workspace', 'telegram', 'manual']; // остальное → other
const cut = (s, n) => String(s ?? '').slice(0, n);
// Даты для Espo — «YYYY-MM-DD HH:mm:ss» в UTC (так хранит сам Espo).
const espoDate = (iso) => {
  if (!iso) return null;
  const d = DateTime.fromISO(String(iso));
  return d.isValid ? d.toUTC().toFormat('yyyy-LL-dd HH:mm:ss') : null;
};
// Бюджет из объекта контракта в строку ≤ 60 символов (поле cBudget — varchar(60)).
function budgetText(bd) {
  if (!bd || typeof bd !== 'object') return null;
  const cur = bd.currency || 'RUB';
  const has = (v) => v !== undefined && v !== null;
  let s = null;
  if (has(bd.min) && has(bd.max) && bd.min !== bd.max) s = `${bd.min}–${bd.max} ${cur}`;
  else if (has(bd.max) || has(bd.min)) s = `${has(bd.max) ? bd.max : bd.min} ${cur}`;
  else if (bd.kind && bd.kind !== 'unknown') s = bd.kind;
  if (s && bd.kind === 'hourly') s += '/ч';
  return s ? cut(s, 60) : null;
}

const consequence = (b.note && String(b.note).trim()) || 'нет ответа — заказ уйдёт другому';
const externalId = cut(b.external_id, 100); // в Espo поле cExternalId — varchar(100); дедуп по нему же

const lead = {
  lastName: cut(b.title, 100),
  description: String(b.text),
  status: 'responded',
  source: ESPO_SOURCES.includes(b.source) ? b.source : 'other',
  cSourceUrl: String(b.url),
  cExternalId: externalId,
  cPublishedAt: espoDate(b.published_at),
  cBudget: budgetText(b.budget),
  cConsequence: consequence,
  cRespondedAt: DateTime.utc().toFormat('yyyy-LL-dd HH:mm:ss'),
};
// Задача follow-up: «Последствие: …» в описании подхватывает сценарий напоминаний.
const task = {
  content: 'Follow-up: ' + cut(b.title, 200),
  description: 'Последствие: ' + consequence + '\n' + String(b.url),
  due_string: 'tomorrow 10:00',
  due_lang: 'en',
};
// id проекта «Обязательства» кэшируется в staticData после первого поиска (нода «Проект «Обязательства»»).
const store = $getWorkflowStaticData('global');
return [{ json: {
  title: String(b.title), external_id: externalId, feed_id: b.id ?? null,
  lead, task, project_id: store.todoist_project_id ? String(store.todoist_project_id) : '',
} }];

// Ищем проект «Обязательства» по имени и кэшируем id в staticData — дальше список не запрашиваем.
const unwrap = (j) => Array.isArray(j) ? j : (Array.isArray(j.results) ? j.results : []);
const list = $input.all().flatMap((i) => unwrap(i.json));
const p = list.find((x) => String(x.name || '').trim().toLowerCase() === 'обязательства');
if (!p) throw new Error('в Todoist нет проекта «Обязательства» (есть: ' + list.map((x) => x.name).join(', ') + ')');
const store = $getWorkflowStaticData('global');
store.todoist_project_id = String(p.id);
return [{ json: { project_id: String(p.id) } }];

// Одно сообщение владельцу на любую ошибку сценария.
// Заголовок берём из самого вебхука — нода «Разбор вебхука» могла упасть сама.
// Текст ошибки: n8n кладёт её в json.error строкой или объектом {message, description}.
function errText(e) {
  if (e === null || e === undefined) return 'неизвестная ошибка';
  if (typeof e === 'string') return e;
  const parts = [e.message, e.description].filter(Boolean);
  return parts.length ? parts.join(' — ') : JSON.stringify(e);
}
let title = '?';
try { const rb = $('Вебхук от портала').first().json.body || {}; title = String((rb.payload || rb).title || '?'); } catch (_) { /* тела нет */ }
// Кэш проекта Todoist сбрасываем: если проект пересоздали, следующий вебхук найдёт его заново.
try { delete $getWorkflowStaticData('global').todoist_project_id; } catch (_) { /* не критично */ }
return [{ json: { text: `⚠ Лента: не удалось создать лид/задачу для ${title}: ${errText($json.error)}` } }];
